import { _ as _export_sfc, o as openBlock, c as createElementBlock, a2 as createStaticVNode } from "./chunks/framework.DiR_5bBd.js";
const __pageData = JSON.parse('{"title":"Сценарии использования","description":"Что можно делать с SymbolTrail: онбординг, объяснение кода, ревью, импакт-анализ, история изменений, подготовка задач, спецификаций и тестов.","frontmatter":{"title":"Сценарии использования","description":"Что можно делать с SymbolTrail: онбординг, объяснение кода, ревью, импакт-анализ, история изменений, подготовка задач, спецификаций и тестов.","section":"Начало работы"},"headers":[],"relativePath":"use-cases.md","filePath":"use-cases.md"}');
